function categoryIcon(category){const c=normalizeSearch(category);let drawing='<rect x="5" y="5" width="6" height="6" rx="1.4"/><rect x="13" y="5" width="6" height="6" rx="1.4"/><rect x="5" y="13" width="6" height="6" rx="1.4"/><rect x="13" y="13" width="6" height="6" rx="1.4"/>';if(c.includes("gelo")||c.includes("natal"))drawing='<path d="M12 2.8v18.4M4 7.4l16 9.2M20 7.4 4 16.6M8.5 4.8 12 7l3.5-2.2M8.5 19.2 12 17l3.5 2.2M4.8 8.5 7 12l-2.2 3.5M19.2 8.5 17 12l2.2 3.5"/>';else if(c.includes("agua")||c.includes("galao")||c.includes("filtro")||c.includes("garrafa"))drawing='<path d="M12 2.8S5.5 10 5.5 14.3a6.5 6.5 0 0 0 13 0C18.5 10 12 2.8 12 2.8Z"/><path d="M9 15.2a3.2 3.2 0 0 0 3.2 3.2"/>';else if(c.includes("piscina")||c.includes("boia")||c.includes("natacao"))drawing='<path d="M3 8c2.2 0 2.2-1.8 4.5-1.8S9.8 8 12 8s2.2-1.8 4.5-1.8S18.8 8 21 8M3 13c2.2 0 2.2-1.8 4.5-1.8S9.8 13 12 13s2.2-1.8 4.5-1.8S18.8 13 21 13M3 18c2.2 0 2.2-1.8 4.5-1.8S9.8 18 12 18s2.2-1.8 4.5-1.8S18.8 18 21 18"/>';else if(c.includes("fruta")||c.includes("polpa")||c.includes("acai")||c.includes("xarope"))drawing='<path d="M12 7c-5.2-4.2-9.3.4-7.5 6.2 1.2 4 4 7.2 7.5 7.2s6.3-3.2 7.5-7.2C21.3 7.4 17.2 2.8 12 7Z"/><path d="M12 7c-.2-3 1.7-4.5 4.5-4.8M12 7c-1.8-2-3.5-2.2-5.2-1.8"/>';else if(c.includes("churrasco")||c.includes("carvao"))drawing='<path d="M12 21c4.3 0 7-2.8 7-6.6 0-2.5-1.4-4.3-3.3-6.4.1 2-1 3.1-2.1 3.7.1-3.7-2-6.7-4.7-8.7.4 4.1-3.6 6.5-3.6 11.4C5.3 18.2 8 21 12 21Z"/>';else if(c.includes("cadeira")||c.includes("camping")||c.includes("aluguel"))drawing='<path d="M7 4v8.5a3 3 0 0 0 3 3h7M7 4h10v8H7M9 15.5 6.5 21M17 15.5l2.5 5"/>';return '<svg class="category-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" focusable="false">'+drawing+'</svg>'}
function buildTabs(){
 const categories=["Todos",...new Set(allProducts.map(p=>p.category).filter(Boolean))];
 $("tabs").innerHTML=categories.map(cat=>{
  const total=cat==="Todos"?allProducts.length:allProducts.filter(p=>p.category===cat).length;
  return '<button type="button" class="tab category-tab" data-cat="'+esc(cat)+'" aria-label="'+esc(cat)+', '+total+' produtos" aria-pressed="'+String(cat===activeCategory)+'">'+categoryIcon(cat)+'<span class="tab-label">'+esc(cat)+'</span><span class="tab-count" aria-hidden="true">'+total+'</span></button>';
 }).join("");
 $("tabs").hidden=false;
}
function normalizeSearch(value){return String(value??"").normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLocaleLowerCase("pt-BR").replace(/[^a-z0-9]+/g," ").trim()}
function editDistance(a,b){if(Math.abs(a.length-b.length)>3)return 99;let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let curr=[i],rowMin=i;for(let j=1;j<=b.length;j++){let v=Math.min(curr[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));curr[j]=v;if(v<rowMin)rowMin=v}if(rowMin>3)return 99;prev=curr}return prev[b.length]}
function searchScore(product,query){const fields=[product.name,product.category,product.desc,product.brand,...(product.flavors||[])].filter(Boolean).map(normalizeSearch);const corpus=fields.join(" ");if(corpus.includes(query))return 0;const words=[...new Set(corpus.split(" ").filter(Boolean))],terms=query.split(" ").filter(Boolean);let score=0;for(const term of terms){let best=99;for(const word of words){if(word===term){best=0;break}if(word.startsWith(term)){best=Math.min(best,1);continue}if(term.length>=3&&word.includes(term)){best=Math.min(best,2);continue}if(term.length>=4&&word.length>=4){const limit=term.length<=5?1:term.length<=9?2:3;const distance=editDistance(term,word);if(distance<=limit)best=Math.min(best,3+distance)}}if(best===99)return null;score+=best}return score}
function renderProducts(){const query=normalizeSearch($("search").value);let arr=allProducts.filter(p=>(activeCategory==="Todos"||p.category===activeCategory)&&(!query||searchScore(p,query)!==null));if(query)arr.sort((a,b)=>(searchScore(a,query)??99)-(searchScore(b,query)??99));let sort=$("sort").value;if(sort==="price-up")arr.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==="price-down")arr.sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));if(sort==="name")arr.sort((a,b)=>a.name.localeCompare(b.name,"pt-BR"));$("products").innerHTML=arr.length?arr.map(p=>`<article class="card"><div class="photo">${p.image ? '<img src="' + esc(p.image) + '" alt="' + esc(p.name) + '" loading="lazy" >' : '<span class="product-symbol" aria-hidden="true">'+categoryIcon(p.category)+'</span>'}</div><span class="tag">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="price">${p.price==null?"Consulte":money(p.price)}</div><div class="unit">${esc(p.unit)}</div>${p.price==null?`<button class="add" data-quote="${esc(p.id)}">Consultar no WhatsApp</button>`:`<button class="add" data-add="${esc(p.id)}">＋ Adicionar ao pedido</button>`}</article>`).join(""):'<p class="empty">Nenhum produto encontrado. Tente um nome parecido ou confira a ortografia.</p>';document.querySelectorAll("[data-cat]").forEach(b=>{const active=b.dataset.cat===activeCategory;b.classList.toggle("active",active);b.setAttribute("aria-pressed",String(active))})}
function renderCart(){let arr=allProducts.filter(p=>bag[p.id]);$("count").textContent=Object.values(bag).reduce((a,b)=>a+b,0);$("cartLines").innerHTML=arr.length?arr.map(p=>{let qty=bag[p.id],price=unitPrice(p,qty);return `<div class="line"><span>${esc(p.name)}<br><b>${money(price*qty)}</b><br><small>${qty} un. × ${money(price)} · ${esc(p.unit)}</small></span><span class="qty"><button data-minus="${esc(p.id)}" aria-label="Diminuir">−</button>${qty}<button data-plus="${esc(p.id)}" aria-label="Aumentar">＋</button></span></div>`}).join(""):'<p class="cart-empty">Seu pedido está vazio.</p>';$("total").textContent=money(arr.reduce((s,p)=>s+unitPrice(p,bag[p.id])*bag[p.id],0))}
document.addEventListener("click",e=>{let cat=e.target.closest("[data-cat]");if(cat){activeCategory=cat.dataset.cat;renderProducts()}let add=e.target.closest("[data-add]"),plus=e.target.closest("[data-plus]"),minus=e.target.closest("[data-minus]"),quote=e.target.closest("[data-quote]");if(quote){let p=allProducts.find(x=>x.id===quote.dataset.quote);let msg="Olá, Águajá Gelajá! Gostaria de consultar preço e disponibilidade: "+(p?.name||"produto do catálogo");if(p?.flavors?.length)msg+="\n\nSabores de interesse: "+p.flavors.join(", ");window.open("https://wa.me/5567981430628?text="+encodeURIComponent(msg)," _blank".trim(),"noopener")}if(add){let id=add.dataset.add;bag[id]=(bag[id]||0)+1;$("cart").classList.remove("hidden");renderCart()}if(plus){let id=plus.dataset.plus;bag[id]=(bag[id]||0)+1;renderCart()}if(minus){let id=minus.dataset.minus;bag[id]--;if(bag[id]<=0)delete bag[id];renderCart()}});
$("search").addEventListener("input",renderProducts);$("sort").addEventListener("change",renderProducts);$("openCart").addEventListener("click",()=>$("cart").classList.toggle("hidden"));$("closeCart").addEventListener("click",()=>$("cart").classList.add("hidden"));$("year").textContent=new Date().getFullYear();
 const sendOrder=(phone)=>{let arr=allProducts.filter(p=>bag[p.id]);if(!arr.length){alert("Adicione ao menos um produto ao pedido.");return}let total=arr.reduce((s,p)=>s+unitPrice(p,bag[p.id])*bag[p.id],0);let lines=arr.map(p=>{let qty=bag[p.id],price=unitPrice(p,qty);return `- ${esc(p.name)} (${esc(p.unit)}) | Quantidade: ${qty} | Unitário: ${money(price)} | ${money(price*qty)}`}).join("\n");let msg="Olá, Águajá Gelajá! Gostaria de fazer este pedido:\n\n"+lines+"\n\nTotal estimado: "+money(total)+"\n\nPodem confirmar a disponibilidade, a taxa de entrega e o valor final, por favor?";window.open("https://wa.me/"+phone+"?text="+encodeURIComponent(msg),"_blank","noopener")};
 $("send").addEventListener("click",()=>sendOrder($("send").dataset.phone));
 $("sendAlt").addEventListener("click",()=>sendOrder($("sendAlt").dataset.phone));

/* Controle de abertura e fechamento do catálogo. */
(() => {
  const catalog = document.getElementById("catalogo");
  const explore = document.getElementById("explorarCatalogo");
  if (!catalog) return;
  const syncCatalog = () => {
    catalog.hidden = window.location.hash !== "#catalogo";
    if (explore) explore.setAttribute("aria-expanded", String(!catalog.hidden));
  };
  syncCatalog();
  window.addEventListener("hashchange", syncCatalog);
  if (explore) {
    explore.addEventListener("click", (event) => {
      event.preventDefault();
      if (catalog.hidden) {
        catalog.hidden = false;
        explore.setAttribute("aria-expanded", "true");
        window.location.hash = "catalogo";
        catalog.scrollIntoView({ behavior: "smooth", block: "start" });
      } else {
        catalog.hidden = true;
        explore.setAttribute("aria-expanded", "false");
        history.replaceState(null, "", window.location.pathname + window.location.search);
        document.getElementById("inicio")?.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    });
  }
})();
